def maya_main_window():
    try:
        ptr = omui1.MQtUtil.mainWindow()
        if ptr:
            return wrapInstance(int(ptr), QtWidgets.QWidget)
    except Exception:
        pass
    return None


def ui_safe(fn):
    """Never let a UI callback throw into Qt; report it in the panel instead."""

    @functools.wraps(fn)
    def wrapper(self, *args, **kwargs):
        try:
            return fn(self, *args, **kwargs)
        except Exception as exc:
            traceback.print_exc()
            try:
                self.set_status("Error: %s" % exc, level="error")
            except Exception:
                pass
    return wrapper


class _WheelGuard(object):
    """Ignore mouse-wheel on unfocused inputs so scrolling the panel never
    changes values by accident."""

    def wheelEvent(self, event):
        if self.hasFocus():
            super(_WheelGuard, self).wheelEvent(event)
        else:
            event.ignore()


class _DoubleSpin(_WheelGuard, QtWidgets.QDoubleSpinBox):
    pass


class _Spin(_WheelGuard, QtWidgets.QSpinBox):
    pass


class _Slider(_WheelGuard, QtWidgets.QSlider):
    pass


class _Combo(_WheelGuard, QtWidgets.QComboBox):
    pass


def _guard_focus(widget):
    widget.setFocusPolicy(QtCore.Qt.StrongFocus)
    return widget


class FloatField(QtWidgets.QWidget):
    """Spin box + slider. The slider covers a soft range; typing can go
    beyond it up to the hard range."""

    changed = QtCore.Signal()
    STEPS = 1000

    def __init__(self, lo, hi, soft_lo=None, soft_hi=None, decimals=3, step=0.1, parent=None):
        super(FloatField, self).__init__(parent)
        self.soft = (lo if soft_lo is None else soft_lo, hi if soft_hi is None else soft_hi)
        lay = QtWidgets.QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(6)
        self.spin = _guard_focus(_DoubleSpin())
        self.spin.setRange(lo, hi)
        self.spin.setDecimals(decimals)
        self.spin.setSingleStep(step)
        self.spin.setKeyboardTracking(False)
        self.spin.setFixedWidth(72)
        self.slider = _guard_focus(_Slider(QtCore.Qt.Horizontal))
        self.slider.setRange(0, self.STEPS)
        lay.addWidget(self.spin)
        lay.addWidget(self.slider, 1)
        self.spin.valueChanged.connect(self._spin_changed)
        self.slider.valueChanged.connect(self._slider_changed)

    def _to_slider(self, v):
        lo, hi = self.soft
        return int(round(clamp((v - lo) / float(hi - lo), 0.0, 1.0) * self.STEPS)) if hi > lo else 0

    def _spin_changed(self, v):
        self.slider.blockSignals(True)
        self.slider.setValue(self._to_slider(v))
        self.slider.blockSignals(False)
        self.changed.emit()

    def _slider_changed(self, i):
        lo, hi = self.soft
        self.spin.setValue(lo + (hi - lo) * i / float(self.STEPS))

    def value(self):
        return float(self.spin.value())

    def setValue(self, v):
        self.spin.blockSignals(True)
        self.slider.blockSignals(True)
        self.spin.setValue(float(v))
        self.slider.setValue(self._to_slider(float(v)))
        self.spin.blockSignals(False)
        self.slider.blockSignals(False)


class IntField(QtWidgets.QWidget):
    changed = QtCore.Signal()

    def __init__(self, lo, hi, soft_lo=None, soft_hi=None, parent=None):
        super(IntField, self).__init__(parent)
        lay = QtWidgets.QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(6)
        self.spin = _guard_focus(_Spin())
        self.spin.setRange(lo, hi)
        self.spin.setKeyboardTracking(False)
        self.spin.setFixedWidth(72)
        self.slider = _guard_focus(_Slider(QtCore.Qt.Horizontal))
        self.slider.setRange(lo if soft_lo is None else soft_lo, hi if soft_hi is None else soft_hi)
        lay.addWidget(self.spin)
        lay.addWidget(self.slider, 1)
        self.spin.valueChanged.connect(self._spin_changed)
        self.slider.valueChanged.connect(self.spin.setValue)

    def _spin_changed(self, v):
        self.slider.blockSignals(True)
        self.slider.setValue(v)
        self.slider.blockSignals(False)
        self.changed.emit()

    def value(self):
        return int(self.spin.value())

    def setValue(self, v):
        self.spin.blockSignals(True)
        self.slider.blockSignals(True)
        self.spin.setValue(int(v))
        self.slider.setValue(int(v))
        self.spin.blockSignals(False)
        self.slider.blockSignals(False)


class ComboField(_Combo):
    changed = QtCore.Signal()

    def __init__(self, items, parent=None):
        super(ComboField, self).__init__(parent)
        _guard_focus(self)
        self.addItems(list(items))
        self.currentIndexChanged.connect(lambda *_: self.changed.emit())

    def value(self):
        return self.currentText()

    def setValue(self, v):
        i = self.findText(str(v))
        if i >= 0:
            self.blockSignals(True)
            self.setCurrentIndex(i)
            self.blockSignals(False)


class CheckField(QtWidgets.QCheckBox):
    changed = QtCore.Signal()

    def __init__(self, text="", parent=None):
        super(CheckField, self).__init__(text, parent)
        self.toggled.connect(lambda *_: self.changed.emit())

    def value(self):
        return self.isChecked()

    def setValue(self, v):
        self.blockSignals(True)
        self.setChecked(bool(v))
        self.blockSignals(False)


class SegmentField(QtWidgets.QWidget):
    """Row of exclusive toggle buttons."""

    changed = QtCore.Signal()

    def __init__(self, items, parent=None, columns=0):
        super(SegmentField, self).__init__(parent)
        lay = QtWidgets.QGridLayout(self) if columns else QtWidgets.QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(2)
        self.group = QtWidgets.QButtonGroup(self)
        self.group.setExclusive(True)
        self.buttons = {}
        for item in items:
            btn = QtWidgets.QPushButton(item)
            btn.setCheckable(True)
            btn.setProperty("unlokSegment", True)
            self.group.addButton(btn)
            if columns:
                lay.addWidget(btn, len(self.buttons) // columns, len(self.buttons) % columns)
            else:
                lay.addWidget(btn)
            self.buttons[item] = btn
        self.buttons[items[0]].setChecked(True)
        self.group.buttonClicked.connect(lambda *_: self.changed.emit())

    def value(self):
        btn = self.group.checkedButton()
        return btn.text() if btn else ""

    def setValue(self, v):
        btn = self.buttons.get(v)
        if btn:
            btn.setChecked(True)


class Section(QtWidgets.QWidget):
    """Collapsible block with a two-column grid (label | field)."""

    def __init__(self, title, expanded=True, parent=None, header=True):
        super(Section, self).__init__(parent)
        lay = QtWidgets.QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)
        self.header = QtWidgets.QToolButton()
        self.header.setText(title)
        self.header.setProperty("unlokSection", True)
        self.header.setCheckable(True)
        self.header.setChecked(expanded)
        self.header.setToolButtonStyle(QtCore.Qt.ToolButtonTextBesideIcon)
        self.header.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
        self.body = QtWidgets.QWidget()
        self.grid = QtWidgets.QGridLayout(self.body)
        self.grid.setContentsMargins(4, 6, 2, 8)
        self.grid.setHorizontalSpacing(8)
        self.grid.setVerticalSpacing(4)
        self.grid.setColumnStretch(1, 1)
        lay.addWidget(self.header)
        lay.addWidget(self.body)
        self.header.toggled.connect(self._toggled)
        self._toggled(expanded)
        self._row = 0
        if not header:  # plain label | field grid inside a step card
            self.header.setVisible(False)
            self.grid.setContentsMargins(0, 0, 0, 0)

    def _toggled(self, on):
        self.header.setArrowType(QtCore.Qt.DownArrow if on else QtCore.Qt.RightArrow)
        self.body.setVisible(on)

    def add_row(self, label, widget, tip=None):
        lbl = QtWidgets.QLabel(label)
        lbl.setMinimumWidth(92)
        if tip:
            lbl.setToolTip(tip)
            widget.setToolTip(tip)
        self.grid.addWidget(lbl, self._row, 0)
        self.grid.addWidget(widget, self._row, 1)
        self._row += 1
        return lbl

    def add_full(self, widget):
        self.grid.addWidget(widget, self._row, 0, 1, 2)
        self._row += 1


def hint_label(text):
    lbl = QtWidgets.QLabel(text)
    lbl.setWordWrap(True)
    lbl.setProperty("unlokHint", True)
    return lbl


def primary_button(text, checkable=False):
    btn = QtWidgets.QPushButton(text)
    btn.setProperty("unlokPrimary", True)
    btn.setCheckable(checkable)
    return btn


def repolish(*widgets):
    """Re-apply the stylesheet after a dynamic property change."""
    for w in widgets:
        w.style().unpolish(w)
        w.style().polish(w)
        w.update()


class ToolHeader(QtWidgets.QWidget):
    """Tool name + one line on what it's for."""

    def __init__(self, title, description, parent=None):
        super(ToolHeader, self).__init__(parent)
        lay = QtWidgets.QVBoxLayout(self)
        lay.setContentsMargins(2, 0, 2, 0)
        lay.setSpacing(1)
        t = QtWidgets.QLabel(title)
        t.setProperty("unlokToolTitle", True)
        d = QtWidgets.QLabel(description)
        d.setWordWrap(True)
        d.setProperty("unlokHint", True)
        lay.addWidget(t)
        lay.addWidget(d)


class NextBanner(QtWidgets.QFrame):
    """'NEXT: ...' strip that always says the one thing to do now."""

    def __init__(self, parent=None):
        super(NextBanner, self).__init__(parent)
        self.setProperty("unlokNext", True)
        lay = QtWidgets.QHBoxLayout(self)
        lay.setContentsMargins(10, 7, 10, 7)
        lay.setSpacing(8)
        self.tag = QtWidgets.QLabel("NEXT")
        self.tag.setProperty("unlokNextTag", True)
        self.tag.setMinimumWidth(64)  # bold + letter-spaced text is wider than its first size hint
        self.tag.setAlignment(QtCore.Qt.AlignTop)
        self.text = QtWidgets.QLabel()
        self.text.setWordWrap(True)
        self.text.setTextFormat(QtCore.Qt.RichText)
        lay.addWidget(self.tag, 0, QtCore.Qt.AlignTop)
        lay.addWidget(self.text, 1)

    def set_text(self, text, tag="NEXT", tone="next"):
        self.tag.setText(tag)
        self.text.setText(text)
        if self.property("unlokTone") != tone:
            self.setProperty("unlokTone", tone)
            self.tag.setProperty("unlokTone", tone)
            repolish(self, self.tag)


class _ClickFrame(QtWidgets.QFrame):
    clicked = QtCore.Signal()

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.LeftButton:
            self.clicked.emit()
        super(_ClickFrame, self).mousePressEvent(event)


class StepCard(QtWidgets.QFrame):
    """A numbered workflow step: badge, title, one-line explanation, body.

    State: 'todo' (grey), 'current' (accent badge, outline and strip) or
    'done' (tick, green strip). Click the header to fold the body away;
    folded, the header shows a one-line summary instead of the explanation.
    auto=True (progressive disclosure): the card opens when it becomes the
    current step (or has a warning) and folds when it's done or not yet
    reached, until you open or close it yourself.
    """

    stateChanged = QtCore.Signal()

    def __init__(self, number, title, subtitle="", parent=None, auto=False):
        super(StepCard, self).__init__(parent)
        self.number = number
        self.auto = auto
        self.setProperty("unlokStep", True)
        lay = QtWidgets.QVBoxLayout(self)
        lay.setContentsMargins(8, 6, 10, 8)
        lay.setSpacing(6)
        self.head = _ClickFrame()
        self.head.setProperty("unlokStepHead", True)
        self.head.setCursor(QtCore.Qt.PointingHandCursor)
        self.head.setToolTip("Click to open or fold this step.")
        self.head.clicked.connect(self.toggle)
        head = QtWidgets.QHBoxLayout(self.head)
        head.setContentsMargins(2, 3, 2, 3)
        head.setSpacing(9)
        self.badge = QtWidgets.QLabel(str(number))
        self.badge.setProperty("unlokBadge", True)
        self.badge.setFixedSize(22, 22)
        self.badge.setAlignment(QtCore.Qt.AlignCenter)
        titles = QtWidgets.QVBoxLayout()
        titles.setSpacing(1)
        self.title = QtWidgets.QLabel(title)
        self.title.setProperty("unlokStepTitle", True)
        titles.addWidget(self.title)
        self.subtitle = QtWidgets.QLabel(subtitle)
        self.subtitle.setWordWrap(True)
        self.subtitle.setProperty("unlokHint", True)
        self._has_subtitle = bool(subtitle)
        titles.addWidget(self.subtitle)
        self.summary = QtWidgets.QLabel("")
        self.summary.setWordWrap(True)
        self.summary.setProperty("unlokSummary", True)
        titles.addWidget(self.summary)
        self.chevron = QtWidgets.QLabel()
        self.chevron.setProperty("unlokChevron", True)
        head.addWidget(self.badge, 0, QtCore.Qt.AlignTop)
        head.addLayout(titles, 1)
        head.addWidget(self.chevron, 0, QtCore.Qt.AlignTop)
        lay.addWidget(self.head)
        self.content = QtWidgets.QWidget()
        self.body = QtWidgets.QVBoxLayout(self.content)
        self.body.setContentsMargins(2, 0, 0, 0)
        self.body.setSpacing(5)
        lay.addWidget(self.content)
        self.state = None
        self.tone = None
        self.expanded = True
        self._user = None  # the user's own open / fold, until the state changes
        self.set_state("todo")
        self._show()

    def add(self, widget, stretch=0):
        self.body.addWidget(widget, stretch)
        return widget

    def add_layout(self, layout):
        self.body.addLayout(layout)
        return layout

    def _show(self):
        self.content.setVisible(self.expanded)
        self.subtitle.setVisible(self._has_subtitle and self.expanded)
        self.summary.setVisible(bool(self.summary.text()) and not self.expanded)
        self.chevron.setText(u"\u25be" if self.expanded else u"\u25b8")

    def _auto_open(self):
        return self.state == "current" or self.tone == "warn"

    def set_expanded(self, on, user=False):
        if user:
            self._user = bool(on)
        if bool(on) != self.expanded:
            self.expanded = bool(on)
            self._show()
            self.stateChanged.emit()

    def toggle(self):
        self.set_expanded(not self.expanded, user=True)

    def enable_auto(self):
        """Turn on progressive disclosure (see the class docstring)."""
        self.auto = True
        self._user = None
        self.set_expanded(self._auto_open())

    def set_summary(self, text, tone=None):
        """The line shown while folded (e.g. what this step found)."""
        changed = tone != self.tone
        self.summary.setText(text or "")
        if changed:
            self.tone = tone
            for w in (self, self.summary):
                w.setProperty("unlokTone", tone or "")
            repolish(self, self.summary)
            if self.auto and self._user is None:
                self.set_expanded(self._auto_open())
            self.stateChanged.emit()
        self._show()

    def set_state(self, state):
        if state == self.state:
            return
        self.state = state
        self.badge.setText(u"\u2713" if state == "done" else str(self.number))
        for w in (self, self.badge, self.title):
            w.setProperty("unlokState", state)
        repolish(self, self.badge, self.title)
        if self.auto:
            self._user = None
            self.set_expanded(self._auto_open())
        self.stateChanged.emit()


class StepNav(QtWidgets.QWidget):
    """A strip of numbered chips, one per step card: coloured by state,
    tooltip = title; click opens that step and scrolls to it."""

    def __init__(self, cards, scroll, parent=None):
        super(StepNav, self).__init__(parent)
        self.cards, self.scroll = cards, scroll
        lay = QtWidgets.QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(3)
        self.chips = []
        for card in cards:
            chip = QtWidgets.QToolButton()
            chip.setProperty("unlokNav", True)
            chip.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
            chip.setMinimumHeight(22)
            chip.setCursor(QtCore.Qt.PointingHandCursor)
            chip.clicked.connect(lambda *_, c=card: self.go(c))
            lay.addWidget(chip)
            self.chips.append(chip)
            card.stateChanged.connect(self.sync)
        self.sync()

    def sync(self):
        for card, chip in zip(self.cards, self.chips):
            chip.setText(u"\u2713" if card.state == "done" else str(card.number))
            chip.setToolTip("Step %d: %s%s" % (card.number, card.title.text(),
                                               (" - %s" % card.summary.text()) if card.summary.text() else ""))
            if chip.property("unlokState") != card.state or chip.property("unlokTone") != (card.tone or ""):
                chip.setProperty("unlokState", card.state)
                chip.setProperty("unlokTone", card.tone or "")
                repolish(chip)

    def go(self, card):
        card.set_expanded(True, user=True)
        QtCore.QTimer.singleShot(0, lambda: self.scroll.ensureWidgetVisible(card, 0, 40))


def scroll_column():
    """A vertical scroll area for step cards; returns (scroll, layout)."""
    scroll = QtWidgets.QScrollArea()
    scroll.setWidgetResizable(True)
    scroll.setFrameShape(QtWidgets.QFrame.NoFrame)
    scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
    body = QtWidgets.QWidget()
    body.setProperty("unlokColumn", True)
    body.setAttribute(QtCore.Qt.WA_StyledBackground, True)
    scroll.viewport().setProperty("unlokColumn", True)
    scroll.viewport().setAttribute(QtCore.Qt.WA_StyledBackground, True)
    lay = QtWidgets.QVBoxLayout(body)
    lay.setContentsMargins(6, 6, 6, 10)
    lay.setSpacing(10)
    scroll.setWidget(body)
    return scroll, lay


def button_row(*buttons):
    w = QtWidgets.QWidget()
    lay = QtWidgets.QHBoxLayout(w)
    lay.setContentsMargins(0, 0, 0, 0)
    lay.setSpacing(4)
    for b in buttons:
        lay.addWidget(b)
    return w


def secondary_button(text, tip=None):
    b = QtWidgets.QPushButton(text)
    if tip:
        b.setToolTip(tip)
    return b


